<script setup lang="ts">import{reactive,watch}from'vue';import DsButton from '@/shared/ui/DsButton.vue';import DsDialog from '@/shared/ui/DsDialog.vue';import DsInput from '@/shared/ui/DsInput.vue';import DsSelect from '@/shared/ui/DsSelect.vue';import type{Menu,MenuInput,Permission}from'../api';const p=defineProps<{open:boolean;menu?:Menu|null;permissions:Permission[];busy?:boolean}>();const emit=defineEmits<{close:[];save:[MenuInput]}>();const f=reactive({code:'',name:'',route:'',icon:'',permission:'',sort_order:'0',active:'true'});watch(()=>[p.open,p.menu]as const,()=>{f.code=p.menu?.Code??'';f.name=p.menu?.Name??'';f.route=p.menu?.Route?.Valid?p.menu.Route.String:'';f.icon=p.menu?.Icon?.Valid?p.menu.Icon.String:'';f.permission=p.menu?.PermissionCode?.Valid?p.menu.PermissionCode.String:'';f.sort_order=String(p.menu?.SortOrder??0);f.active=String(p.menu?.Active??true)},{immediate:true});function payload():MenuInput{return{code:p.menu?undefined:f.code,name:f.name,route:f.route||null,icon:f.icon||null,permission:f.permission||null,sort_order:Number(f.sort_order)||0,active:f.active==='true',parent_id:null}}</script><template><DsDialog :open="open" :title="menu?'Edit menu':'Add menu'" description="Navigation visibility may reference a permission, but backend authorization remains authoritative." @close="emit('close')"><div class="form"><DsInput v-if="!menu" v-model="f.code" label="Code"/><DsInput v-model="f.name" label="Name"/><DsInput v-model="f.route" label="Route" placeholder="/reports"/><DsInput v-model="f.icon" label="Icon"/><DsSelect v-model="f.permission" label="Visibility permission" :options="[{label:'None',value:''},...permissions.map(x=>({label:x.Name,value:x.Code}))]"/><DsInput v-model="f.sort_order" label="Sort order" type="number"/><DsSelect v-model="f.active" label="Status" :options="[{label:'Active',value:'true'},{label:'Inactive',value:'false'}]"/></div><template #footer><DsButton variant="secondary" @click="emit('close')">Cancel</DsButton><DsButton :disabled="busy||!f.name||(!menu&&!f.code)" @click="emit('save',payload())">{{busy?'Saving…':'Save menu'}}</DsButton></template></DsDialog></template><style scoped>.form{display:grid;gap:16px}</style>